def check(ctx):
    held = ctx.held_object()
    if held != "u_brown":
        return None
    j = ctx.joint("finger_joint")
    if j is None:
        return None
    e = j["effort"]
    if e < 0:
        e = -e
    if e > ctx.value("max_effort"):
        return {"value": e, "detail": "finger_joint effort exceeded u_brown's tolerated clamp effort while held"}
    return None

def check(ctx):
    held = ctx.held_object()
    if held != "u_brown":
        ctx.state["ref"] = None
        return None
    rel = ctx.transform("tcp", "u_brown")
    pos = rel["translation"]
    if ctx.state.get("ref") is None:
        ctx.state["ref"] = pos
        return None
    d = ctx.dist(ctx.state["ref"], pos)
    if d > ctx.value("slip_tol"):
        return {"value": d, "detail": "u_brown shifted relative to gripper (slip) by " + str(d) + " m while held"}
    return None

def check(ctx):
    d = ctx.depth()
    if d is None:
        return None
    if "ref" not in ctx.state:
        ctx.state["ref"] = d.copy()
        return None
    diff = np.abs(d - ctx.state["ref"])
    changed = np.nanmean(diff)
    if changed > ctx.value("change_m"):
        return {"value": float(changed), "detail": "workspace depth image changed beyond baseline, possible unexpected object/event"}
    return None

